// Parse Input: extract the rug category (and optional "focus:" line) from chat.
const input = $input.first().json.chatInput || '';

const categories = [
  { key: 'area_rug', display: 'Area Rug', patterns: ['area rug', 'area rugs'] },
  { key: 'outdoor_rug', display: 'Outdoor Rug', patterns: ['outdoor rug', 'outdoor rugs', 'patio rug'] },
  { key: 'hallway_runner', display: 'Hallway Runner', patterns: ['hallway runner', 'runner rug', 'hall runner', 'runners'] },
  { key: 'shag_rug', display: 'Shag Rug', patterns: ['shag rug', 'shag rugs', 'shaggy rug'] }
];

const lowerInput = input.toLowerCase();
let match = null;
for (const cat of categories) {
  if (cat.patterns.some(p => lowerInput.includes(p))) { match = cat; break; }
}

const focusMatch = input.match(/focus\s*:\s*([^\n]+)/i);
const focus = focusMatch ? focusMatch[1].trim() : '';

return [{
  json: {
    selectedCategory: match ? match.display : null,
    categoryKey: match ? match.key : null,
    focus,
    hasValidInput: !!match,
    errorReason: match ? null : 'no_category'
  }
}];

// Error Response: explain in chat why no report was produced.
const input = $input.first().json;
const reason = input.errorReason || 'unknown';

let message;
if (reason === 'no_category') {
  message = 'I could not detect a rug category. Send one of: Area Rug, Outdoor Rug, Hallway Runner, Shag Rug. Optionally add a second line such as "focus: washable".';
} else if (reason === 'missing_retailer_data') {
  message = 'No report was generated: the product API returned no usable products for ' + (input.missingRetailers || []).join(', ') +
    '. A competitor comparison needs Wayfair, Amazon and Walmart data. Try again in a few minutes.';
} else {
  message = 'An unknown error occurred. Check the execution log in n8n.';
}

return [{ json: { error: true, reason, output: message } }];

// Compute Competitor Metrics
// Normalizes the three retailer responses and computes every number the report uses.
// The AI agents only interpret these numbers; they never calculate their own.
const parsed = $('Parse Input').first().json;
const RETAILERS = ['wayfair', 'amazon', 'walmart'];
const LABEL = { wayfair: 'Wayfair', amazon: 'Amazon', walmart: 'Walmart' };
const PREFIX = { wayfair: 'WF', amazon: 'AZ', walmart: 'WM' };

// ---------- group API responses by source ----------
const raw = {};
const scrapedAt = {};
for (const item of $input.all()) {
  const r = item.json || {};
  const src = String(r.source || '').toLowerCase();
  if (!RETAILERS.includes(src)) continue;
  raw[src] = (r.products || []).slice(0, 10);
  scrapedAt[src] = r.scraped_at || null;
}

// ---------- parsing helpers ----------
function firstNumber(v) {
  const m = String(v == null ? '' : v).replace(/,/g, '').match(/\d+(?:\.\d+)?/);
  return m ? parseFloat(m[0]) : null;
}

// Rug size from the title, e.g. 8x10, 5'x7', 9' x 12', 5ft x 8ft, 5'3" x 7'6", 63"x31.5"
// feet, optional inches ("2'6", "2'-3\"", "5'3\""), or a bare number
const DIM = String.raw`(\d{1,3}(?:\.\d+)?)\s*(ft\.?|feet|foot|'|"|in\.?|inch(?:es)?)?(?:\s*-?\s*(\d{1,2})\s*(?:"|in\.?)?)?`;
const SIZE_RE = new RegExp(String.raw`(?<![\d.'"-])` + DIM + String.raw`\s*[x×]\s*` + DIM, 'i');
function toFeet(n, unit, extraIn) {
  n = parseFloat(n);
  const u = (unit || '').toLowerCase();
  if (u.startsWith('f') || u === "'") return n + (extraIn ? parseFloat(extraIn) / 12 : 0);
  return n > 20 ? n / 12 : n; // inches, or a typo like 8"x10" that really means feet
}
function parseSize(text) {
  const s = String(text || '').replace(/[’′]/g, "'").replace(/[”″]/g, '"');
  const m = s.match(SIZE_RE);
  if (!m) return null;
  const a = toFeet(m[1], m[2], m[3]);
  const b = toFeet(m[4], m[5], m[6]);
  if (!(a >= 1.5 && a <= 20 && b >= 1.5 && b <= 20)) return null;
  const fmt = x => (Math.round(x * 10) / 10).toString();
  return { label: fmt(a) + ' x ' + fmt(b) + ' ft', sqft: Math.round(a * b * 10) / 10 };
}

const FEATURES = {
  'Washable': /washable/i,
  'Non-slip backing': /non[\s-]?slip|anti[\s-]?slip|no[\s-]?slip|non[\s-]?skid/i,
  'Indoor/outdoor': /outdoor|water[\s-]?resistant|weather/i,
  'Shag / high pile': /shag|fluffy|plush|fuzzy|high[\s-]?pile/i,
  'Low pile / flatweave': /low[\s-]?pile|low[\s-]?profile|flat[\s-]?weave|thin/i,
  'Natural fiber': /\bjute\b|\bwool\b|\bsisal\b|\bcotton\b|\bseagrass\b/i,
  'Designer collaboration': /\bx\s+loloi\b|\bloloi\b/i
};
const STYLES = {
  'Boho / Moroccan': /boho|moroccan|bohemian/i,
  'Vintage / traditional': /vintage|distress|traditional|persian|oriental|medallion/i,
  'Abstract': /abstract/i,
  'Geometric / checkered': /geometric|checker|plaid|diamond|trellis|stripe/i,
  'Floral / botanical': /floral|botanical/i,
  'Modern / contemporary': /modern|contemporary/i,
  'Coastal': /coastal|nautical/i,
  'Solid / neutral': /\bsolid\b|neutral/i
};

// Brand guess from the listing title. Wayfair titles are product names, so only
// collaborations like "x Loloi" are detected there.
const NOT_BRANDS = new Set(('area rug rugs washable large small modern boho shag ultra soft fluffy checkered abstract vintage ' +
  'black white blue grey gray ivory cream beige brown red green pink navy tan indoor outdoor the super machine plush fuzzy ' +
  'round runner runners hallway kitchen living bedroom upgrade doormat entryway floral geometric moroccan neutral natural ' +
  'light dark multi performance extra thick thin non-slip nonslip fluffy shaggy faux premium luxury new set pack door mat ' +
  'washable-rug contemporary traditional oriental persian bathroom dining office nursery kids jute wool cotton').split(/\s+/));
// Multi-word brands that the first-word rule would cut short.
const BRAND_PATTERNS = [
  [/by drew barrymore/i, 'BEAUTIFUL BY DREW BARRYMORE'],
  [/^jonathan\s+y\b/i, 'JONATHAN Y'],
  [/^nicole\s+miller\b/i, 'NICOLE MILLER'],
  [/^better\s+homes/i, 'BETTER HOMES & GARDENS'],
  [/^my\s+texas\s+house\b/i, 'MY TEXAS HOUSE'],
  [/^stone\s*&\s*beam\b/i, 'STONE & BEAM'],
  [/^amazon\s+basics\b/i, 'AMAZON BASICS']
];
// Retailer-owned private labels: competitors' own brands, not suppliers Wayfair can recruit.
const PRIVATE_LABELS = { 'MAINSTAYS': 'Walmart', 'BETTER HOMES & GARDENS': 'Walmart', 'BEAUTIFUL BY DREW BARRYMORE': 'Walmart', 'MY TEXAS HOUSE': 'Walmart', 'AMAZON BASICS': 'Amazon', 'STONE & BEAM': 'Amazon', 'RIVET': 'Amazon' };
function brandOf(retailer, title) {
  if (/\bloloi\b/i.test(title)) return 'LOLOI';
  if (retailer === 'wayfair') return null;
  for (const [re, name] of BRAND_PATTERNS) if (re.test(title)) return name;
  const first = (title.trim().split(/[\s,:;|]+/)[0] || '').replace(/[^A-Za-z&'-]/g, '').toUpperCase();
  if (first.length < 3 || NOT_BRANDS.has(first.toLowerCase())) return null;
  return first;
}

// ---------- normalize products ----------
const products = [];
const productsBy = {};
for (const r of RETAILERS) {
  productsBy[r] = (raw[r] || []).map((p, i) => {
    let title = String(p.name || '').trim();
    let variant = '';
    const v = title.match(/^(.*?),\s*variant on\s+(.+)$/i); // Walmart: "Color, variant on TITLE"
    if (v) { variant = v[1].trim(); title = v[2].trim(); }
    const text = [title, (p.details || []).join(' '), p.pattern || ''].join(' ');
    const size = parseSize(title);
    const price = firstNumber(p.price);
    const prod = {
      id: PREFIX[r] + (i + 1),
      retailer: r,
      retailerLabel: LABEL[r],
      title,
      variant,
      url: p.url || '',
      imageUrl: p.image_url || '',
      price: price && price > 0 ? price : null,
      rating: firstNumber(p.rating),
      reviews: firstNumber(p.review_count),
      size: size ? size.label : null,
      sqft: size ? size.sqft : null,
      pricePerSqft: size && price ? Math.round((price / size.sqft) * 100) / 100 : null,
      brand: brandOf(r, title),
      features: Object.keys(FEATURES).filter(k => FEATURES[k].test(text)),
      styles: Object.keys(STYLES).filter(k => STYLES[k].test(text))
    };
    products.push(prod);
    return prod;
  });
}

// ---------- fail loudly if a retailer is missing ----------
const missing = RETAILERS.filter(r => !productsBy[r].some(p => p.price !== null)).map(r => LABEL[r]);
if (missing.length) {
  return [{ json: { ok: false, errorReason: 'missing_retailer_data', missingRetailers: missing } }];
}

// ---------- statistics ----------
const round2 = x => (x == null ? null : Math.round(x * 100) / 100);
function median(arr) {
  const a = arr.filter(x => x != null).sort((x, y) => x - y);
  if (!a.length) return null;
  const m = Math.floor(a.length / 2);
  return a.length % 2 ? a[m] : (a[m - 1] + a[m]) / 2;
}
function mean(arr) {
  const a = arr.filter(x => x != null);
  return a.length ? a.reduce((s, x) => s + x, 0) / a.length : null;
}
const BANDS = [
  { label: 'Under $30', min: 0, max: 30 },
  { label: '$30-$74', min: 30, max: 75 },
  { label: '$75-$149', min: 75, max: 150 },
  { label: '$150-$299', min: 150, max: 300 },
  { label: '$300+', min: 300, max: Infinity }
];
const countBy = (list, key) => {
  const out = {};
  for (const p of list) for (const k of p[key]) out[k] = (out[k] || 0) + 1;
  return out;
};

const retailers = {};
for (const r of RETAILERS) {
  const list = productsBy[r];
  const prices = list.map(p => p.price);
  const priced = prices.filter(x => x != null);
  const topReviewed = list.filter(p => p.reviews != null).sort((a, b) => b.reviews - a.reviews)[0] || null;
  const brandCounts = {};
  list.forEach(p => { if (p.brand) brandCounts[p.brand] = (brandCounts[p.brand] || 0) + 1; });
  retailers[r] = {
    label: LABEL[r],
    listings: list.length,
    pricedListings: priced.length,
    priceMin: round2(Math.min(...priced)),
    priceMax: round2(Math.max(...priced)),
    priceMedian: round2(median(prices)),
    priceMean: round2(mean(prices)),
    priceBands: BANDS.map(b => ({ band: b.label, count: priced.filter(x => x >= b.min && x < b.max).length })),
    avgRating: round2(mean(list.map(p => p.rating))),
    medianReviews: median(list.map(p => p.reviews)),
    totalReviews: list.reduce((s, p) => s + (p.reviews || 0), 0),
    listingsUnder10Reviews: list.filter(p => p.reviews != null && p.reviews < 10).length,
    listingsWithSize: list.filter(p => p.sqft).length,
    medianPricePerSqft: round2(median(list.map(p => p.pricePerSqft))),
    features: countBy(list, 'features'),
    styles: countBy(list, 'styles'),
    brands: brandCounts,
    topReviewed: topReviewed ? { id: topReviewed.id, title: topReviewed.title, reviews: topReviewed.reviews, price: topReviewed.price } : null
  };
}

// ---------- cross-retailer signals ----------
const featureGaps = Object.keys(FEATURES).map(f => ({
  feature: f,
  wayfair: retailers.wayfair.features[f] || 0,
  amazon: retailers.amazon.features[f] || 0,
  walmart: retailers.walmart.features[f] || 0
})).filter(g => g.amazon + g.walmart >= 3 && g.wayfair <= 1);

const styleGaps = Object.keys(STYLES).map(s => ({
  style: s,
  wayfair: retailers.wayfair.styles[s] || 0,
  amazon: retailers.amazon.styles[s] || 0,
  walmart: retailers.walmart.styles[s] || 0
})).filter(g => g.amazon + g.walmart >= 3 && g.wayfair <= 1);

const priceBandGaps = BANDS.map((b, i) => ({
  band: b.label,
  wayfair: retailers.wayfair.priceBands[i].count,
  amazon: retailers.amazon.priceBands[i].count,
  walmart: retailers.walmart.priceBands[i].count
})).filter(g => (g.wayfair === 0 && g.amazon + g.walmart >= 3) || (g.wayfair >= 3 && g.amazon + g.walmart === 0));

const brandMap = {};
for (const p of products) {
  if (!p.brand) continue;
  const b = brandMap[p.brand] || (brandMap[p.brand] = { brand: p.brand, retailers: new Set(), listings: 0, totalReviews: 0, ids: [], minPrice: null, maxPrice: null });
  b.retailers.add(p.retailerLabel);
  b.listings++;
  b.totalReviews += p.reviews || 0;
  b.ids.push(p.id);
  if (p.price != null) {
    b.minPrice = b.minPrice == null ? p.price : Math.min(b.minPrice, p.price);
    b.maxPrice = b.maxPrice == null ? p.price : Math.max(b.maxPrice, p.price);
  }
}
const brands = Object.values(brandMap)
  .map(b => ({ ...b, retailers: [...b.retailers], onSampledWayfair: b.retailers.has('Wayfair'), privateLabelOf: PRIVATE_LABELS[b.brand] || null }))
  .sort((a, b) => b.totalReviews - a.totalReviews);

const metrics = {
  retailers,
  crossRetailer: {
    medianPriceGapVsAmazon: round2(retailers.wayfair.priceMedian - retailers.amazon.priceMedian),
    medianPriceGapVsWalmart: round2(retailers.wayfair.priceMedian - retailers.walmart.priceMedian),
    featureGaps,
    styleGaps,
    priceBandGaps,
    brands,
    supplierLeads: brands.filter(b => !b.onSampledWayfair && !b.privateLabelOf).slice(0, 8)
  }
};

// ---------- prompt context shared by every agent ----------
const snapshotDates = RETAILERS.map(r => scrapedAt[r]).filter(Boolean).map(d => d.slice(0, 10));
const snapshot = [...new Set(snapshotDates)].join(', ') || 'unknown';
const money = x => (x == null ? 'n/a' : '$' + x.toFixed(2));
const productLines = products.map(p => [
  p.id,
  p.retailerLabel,
  money(p.price),
  (p.rating != null ? p.rating + ' stars' : 'no rating') + ' (' + (p.reviews != null ? p.reviews.toLocaleString('en-US') : '0') + ' reviews)',
  'size: ' + (p.size || 'not in title'),
  p.pricePerSqft != null ? money(p.pricePerSqft) + '/sq ft' : '',
  'brand: ' + (p.brand || 'unknown'),
  p.features.length ? 'features: ' + p.features.join(', ') : '',
  p.title.slice(0, 140)
].filter(Boolean).join(' | '));

const promptContext = [
  'CATEGORY: ' + parsed.selectedCategory,
  'FOCUS: ' + (parsed.focus || 'none'),
  'PERSPECTIVE: You work for Wayfair. "Wayfair" is us; Amazon and Walmart are competitors.',
  'DATA: ' + RETAILERS.map(r => retailers[r].listings + ' ' + LABEL[r]).join(', ') +
    ' listings, one snapshot scraped ' + snapshot + '. No sales, conversion, traffic or price-history data exists.',
  'NOTE: Wayfair titles rarely include rug size, so Wayfair price-per-square-foot is based on ' +
    retailers.wayfair.listingsWithSize + ' of ' + retailers.wayfair.listings + ' listings. Treat Wayfair list prices as "starting at" prices.',
  '',
  'RETAILER METRICS (computed in code; use these exact numbers):',
  JSON.stringify(retailers),
  '',
  'CROSS-RETAILER SIGNALS (computed in code):',
  JSON.stringify(metrics.crossRetailer),
  '',
  'PRODUCTS (cite by ID):',
  productLines.join('\n')
].join('\n');

return [{
  json: {
    ok: true,
    category: parsed.selectedCategory,
    categoryKey: parsed.categoryKey,
    focus: parsed.focus,
    snapshot,
    metrics,
    products,
    promptContext
  }
}];

