// Collect Sections: gather every agent's HTML plus the computed data.
// Node names here must match the agent node names exactly (case-sensitive).
const AGENTS = {
  executive: 'Executive Summary Agent',
  competitors: 'Competitor Analysis Agent',
  comparison: 'Comparison Agent',
  pricing: 'Pricing & Whitespace Agent',
  suppliers: 'Supplier Identification Agent',
  recommendations: 'Recommendations Agent'
};

const sections = {};
for (const [key, nodeName] of Object.entries(AGENTS)) {
  try { sections[key] = String($(nodeName).first().json.output || ''); } catch (e) { sections[key] = ''; }
}

const data = $('Compute Competitor Metrics').first().json;

return [{
  json: {
    sections,
    metadata: {
      category: data.category,
      categoryKey: data.categoryKey,
      focus: data.focus,
      snapshot: data.snapshot,
      date: new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })
    },
    metrics: data.metrics,
    products: data.products
  }
}];

// Assemble HTML Report
// Cleans each agent section, adds code-built tables (comparison + product appendix),
// and wraps everything in one styled, self-contained HTML page.
var data = $input.first().json;
var sections = data.sections || {};
var meta = data.metadata || {};
var metrics = data.metrics || {};
var products = data.products || [];
var R = metrics.retailers || {};
var RETAILERS = ['wayfair', 'amazon', 'walmart'];

function esc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function money(x) { return x == null ? 'n/a' : '$' + Number(x).toFixed(2); }

// ---- 1. Strip model chatter before/after each <section> ----
Object.keys(sections).forEach(function (k) {
  var s = String(sections[k] || '').replace(/```html\s*/gi, '').replace(/```\s*/g, '').replace(/\\n/g, '\n').replace(/\\"/g, '"');
  var a = s.indexOf('<section');
  var b = s.lastIndexOf('</section>');
  sections[k] = (a > -1 && b > a) ? s.slice(a, b + 10) : '';
});

// ---- 2. Formatting cleanup (from the Phase 2 report): Markdown -> HTML, no italics, hashtag pills ----
var CATEGORY_NAMES = { area_rug: 'Area Rug', outdoor_rug: 'Outdoor Rug', hallway_runner: 'Hallway Runner', shag_rug: 'Shag Rug' };
function fixText(t) {
  t = t.replace(/(^|\n)[ \t]*#{1,6}[ \t]+([^\n]+)/g, function (m, pre, h) { return pre + '<h4>' + h.trim() + '</h4>'; });
  t = t.replace(/\*\*([^*\n]{1,200}?)\*\*/g, '<strong>$1</strong>');
  t = t.replace(/__([^_\n]{1,200}?)__/g, '<strong>$1</strong>');
  t = t.replace(/(^|[\s(>])\*([^*\s][^*\n]{0,150}?)\*(?=[\s.,;:!?)<]|$)/g, '$1$2');
  t = t.replace(/\*\*/g, '');
  t = t.replace(/(?:^|\n)((?:[ \t]*[-•*][ \t]+[^\n]+(?:\n|$))+)/g, function (m, block) {
    var items = block.split('\n').map(function (l) { return l.replace(/^[ \t]*[-•*][ \t]+/, '').trim(); }).filter(Boolean);
    return '\n<ul>' + items.map(function (i) { return '<li>' + i + '</li>'; }).join('') + '</ul>\n';
  });
  t = t.replace(/\b(area_rug|outdoor_rug|hallway_runner|shag_rug)\b/g, function (m) { return CATEGORY_NAMES[m] || m; });
  t = t.replace(/(^|[\s(>,])#([A-Za-z][A-Za-z0-9_]{1,40})\b/g, function (m, pre, tag) {
    if (/^[0-9a-fA-F]{3,8}$/.test(tag)) return m;
    return pre + '<span class="hashtag">#' + tag + '</span>';
  });
  return t;
}
function formatFix(html) {
  var keep = [];
  html = html.replace(/<(style|script)[\s\S]*?<\/\1>/gi, function (m) { keep.push(m); return '\u0000' + (keep.length - 1) + '\u0000'; });
  var parts = html.split(/(<[^>]+>)/);
  for (var i = 0; i < parts.length; i++) { if (parts[i] && parts[i].charAt(0) !== '<') parts[i] = fixText(parts[i]); }
  html = parts.join('');
  html = html.replace(/<\/?(em|i)(\s[^>]*)?>/gi, '');
  return html.replace(/\u0000(\d+)\u0000/g, function (m, n) { return keep[+n]; });
}
Object.keys(sections).forEach(function (k) { sections[k] = formatFix(sections[k]); });

// ---- 3. Visible placeholder for any section an agent failed to produce ----
var TITLES = {
  executive: 'Executive Summary', competitors: 'Competitor Analysis', comparison: 'Head-to-Head Comparison',
  pricing: 'Pricing & Whitespace', suppliers: 'Supplier Identification', recommendations: 'Recommendations'
};
var missingSections = [];
Object.keys(TITLES).forEach(function (k) {
  if (!sections[k]) {
    missingSections.push(TITLES[k]);
    sections[k] = '<section class="section-missing"><h2>' + esc(TITLES[k]) + '</h2><p>This section was not generated in this run: the AI agent returned no usable HTML. Check the agent node in the n8n execution and rerun.</p></section>';
  }
});

// ---- 4. Code-built comparison table (exact numbers, never AI-written) ----
function row(label, fn, note) {
  return '<tr><th scope="row">' + esc(label) + (note ? '<span class="row-note">' + esc(note) + '</span>' : '') + '</th>' +
    RETAILERS.map(function (r) { return '<td' + (r === 'wayfair' ? ' class="us"' : '') + '>' + fn(R[r] || {}) + '</td>'; }).join('') + '</tr>';
}
function ofN(key, name) {
  return function (x) { return ((x[key] || {})[name] || 0) + ' of ' + (x.listings || 0); };
}
var FEATURE_ROWS = ['Washable', 'Non-slip backing', 'Indoor/outdoor', 'Shag / high pile', 'Low pile / flatweave', 'Natural fiber', 'Designer collaboration'];
var comparisonTable =
  '<div class="table-wrap"><table class="data-table compare-table"><thead><tr><th>Metric</th><th class="us">Wayfair</th><th>Amazon</th><th>Walmart</th></tr></thead><tbody>' +
  row('Listings analyzed', function (x) { return x.listings; }) +
