// Validate Report: check every section made it in and flag content worth a human look.
const input = $input.first().json;
const html = input.cleanedHtml || '';

const required = {
  'Executive Summary': 'id="executive"',
  'Competitor Analysis': 'id="competitors"',
  'Comparison': 'id="comparison"',
  'Pricing & Whitespace': 'id="pricing"',
  'Supplier Identification': 'id="suppliers"',
  'Recommendations': 'id="recommendations"'
};

const warnings = [];
const sectionsFound = Object.keys(required).filter(k => html.includes(required[k]));
const missing = input.missingSections || [];
missing.forEach(s => warnings.push('Section not generated: ' + s));
if (!html.includes('</html>')) warnings.push('HTML may be truncated');

// Visible text only (drop the <style> block and tags)
const text = html.replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ');
if (/\*\*|```/.test(text)) warnings.push('Leftover Markdown found');

// Percentages are allowed only next to a count; list them so a human can check.
const percents = text.match(/[^.]{0,60}\d+(?:\.\d+)?\s?%[^.]{0,40}/g) || [];
if (percents.length) warnings.push(percents.length + ' percentage claim(s) to double-check, e.g. "' + percents[0].replace(/^\S*\s+/, '').trim() + '"');

return [{
  json: {
    cleanedHtml: html,
    validation: {
      isValid: missing.length === 0 && html.includes('</html>'),
      sectionsGenerated: (sectionsFound.length - missing.length) + ' of ' + Object.keys(required).length,
      warnings
    }
  }
}];

// Download Report: turn the HTML into a downloadable file and reply in chat.
const input = $input.first().json;
const html = input.cleanedHtml || '';
const validation = input.validation || {};
const category = $('Parse Input').first().json.selectedCategory || 'Rug';

const dateStr = new Date().toISOString().split('T')[0];
const fileName = category.toLowerCase().replace(/\s+/g, '_') + '_competitor_report_' + dateStr + '.html';

const lines = [
  category + ' competitor report is ready: ' + fileName,
  'Sections generated: ' + (validation.sectionsGenerated || 'unknown') + '.',
  'Download it from this execution: open the "Download Report" node, Binary tab, then Download.'
];
if ((validation.warnings || []).length) lines.push('Warnings: ' + validation.warnings.join(' | '));

return [{
  json: { output: lines.join('\n'), fileName, validation, category, generatedAt: new Date().toISOString() },
  binary: {
    data: {
      data: Buffer.from(html, 'utf8').toString('base64'),
      mimeType: 'text/html',
      fileName
    }
  }
}];

